// TestAddItem: operation addItem, golden scenario.
func TestAddItem(t *testing.T) {
	// Given a clerk and a red lamp in stock
	// When addItem is called for a green lamp
	// Then it answers 201 with the item, both lamps are kept, and ItemAdded is published
	h := newHarness(t)
	h.SignIn(t, "clerk")
	h.Insert(t, "items", Record{"colour": Value{Kind: "enum", Text: "red"}, "name": Value{Kind: "string", Text: "red lamp"}, "price": Value{Kind: "decimal", Text: "12.50"}, "reserved": Value{Kind: "int", Text: "1"}, "stock": Value{Kind: "int", Text: "2"}})
	got := h.Request(t, "addItem", "POST", "/items", Record{"colour": Value{Kind: "enum", Text: "green"}, "name": Value{Kind: "string", Text: "green lamp"}, "price": Value{Kind: "decimal", Text: "12.50"}, "stock": Value{Kind: "int", Text: "1"}})
	expectStatus(t, got, 201)
	expectBody(t, got, Record{"colour": Value{Kind: "enum", Text: "green"}, "name": Value{Kind: "string", Text: "green lamp"}})
	expectState(t, h, "items", Record{"name": Value{Kind: "string", Text: "red lamp"}})
	expectState(t, h, "items", Record{"name": Value{Kind: "string", Text: "green lamp"}})
	expectEmitted(t, h, "items/ItemAdded")
}

